#!/bin/bash
# Expect script for WeChat QR login
# Usage: ./wechat-relogin.sh

set -e

CHANNEL="openclaw-weixin"
LOGFILE="/tmp/wechat-login-$(date +%Y%m%d_%H%M%S).log"

echo "=== OpenClaw WeChat Re-Login ==="
echo "Log file: $LOGFILE"
echo ""

# Check if we have a terminal
if [ ! -t 0 ]; then
    echo "Error: No terminal (STDIN not a TTY)"
    echo "QR login requires interactive terminal for phone scanning"
    echo ""
    echo "To re-login manually, run:"
    echo "  openclaw channels login --channel openclaw-weixin"
    echo ""
    echo "Then scan the QR code with your phone WeChat app"
    exit 1
fi

spawn openclaw channels login --channel $CHANNEL

expect {
    "二维码" {
        send_user "Please scan the QR code with your phone WeChat app\n"
    }
    "timeout" {
        send_user "Timeout waiting for QR code\n"
        exit 1
    }
    eof {
        send_user "Process ended unexpectedly\n"
        exit 1
    }
}

expect {
    "确认登录" {
        send "\r"
        exp_continue
    }
    "连接成功" {
        send_user "Connected successfully!\n"
    }
    "timeout" {
        send_user "Timeout waiting for confirmation\n"
        exit 1
    }
    eof {
        send_user "Login process ended\n"
    }
}

wait
EOF
chmod +x /tmp/wechat-relogin.sh
echo "Script ready"

